/// <summary>
///     Data provider class for <c>AVAsmmActivitiesWeeklyPlanADMReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data provider class for the <c>AVAsmmActivitiesWeeklyPlanADMReport</c> SSRS Report.
/// </remarks>
[
    SRSReportQueryAttribute(queryStr(AVAsmmActivitiesWeeklyPlanADMReportQry)),
    SRSReportParameterAttribute(classStr(AVAsmmActivitiesWeeklyPlanADMReportContract))
]
class AVAsmmActivitiesWeeklyPlanADMReportDP extends SrsReportDataProviderPreProcess //SRSReportDataProviderBase
{
    AVAActivitiesWeeklyPlanReportHeaderTmp          clsHeaderTmp;
    AVAActivitiesWeeklyPlanReportHeaderTmp          clsHeaderTmpBase;
    AVAActivitiesWeeklyPlanReportDetailTmp          clsDetailTmp;
    AVAActivitiesWeeklyPlanReportDetailTmp          clsDetailTmpBase;

    AVAsmmActivitiesWeeklyPlanADMReportContract     clsReportContract;
    RefRecId                                        clsSalesQuotationTableRecId;

    CompanyInfo                                     clsCompanyInfo;
    CompanyImage                                    clsCompanyLogo;
    Bitmap                                          clsCompanyLogoBitmap;
    container                                       clsAllBPCompanies;

    SysDocuBrandDetails                             clsSysDocuBrandDetails;

    date                                            clsToday;
    int                                             clsTodayDayOfWeek;
    TimeZone                                        clsTimeZone;
    LanguageId                                      clsLanguageId;

    AVAEvaluationDateFrom                           clsAVAEvaluationDateFrom;
    AVAEvaluationDateTo                             clsAVAEvaluationDateTo;
    AVAEvaluationDateFrom                           clsAVAEvaluationDateFromCalc;
    AVAEvaluationDateTo                             clsAVAEvaluationDateToCalc;
    utcdatetime                                     clsAVAEvaluationDateFromQuery;
    utcdatetime                                     clsAVAEvaluationDateToQuery;

    smmActivities                                   clssmmActivities;

    int                                             clsAdditionalInfoLevel;

}

Method.Source:
/// <summary>
///     AVA <c>initialize</c> method.
/// </summary>
/// <remarks>
///     This method can be overridden by application developers to add any initialization logic needed.
///     This method is invoked by framework before <c>processReport</c> report is invoked.
/// </remarks>
public void initialize()
{
    this.setContractAndParamValues();
}

/// <summary>
///     AVA <c>processReport</c> method.
/// </summary>
public void processReport()
{
    Query                   locQuery;
    QueryBuildDataSource    locQBDSQuotation;
    QueryRun                locQueryRun;
    QueryBuildRange         locQueryBuildRange;
    str                     locDateTimeRange;

    QueryBuildDataSource    locQBDSRequest;
    QueryBuildDataSource    locQBDSSalesGroup;

    locQuery    = this.parmQuery();
    locQueryRun = new queryRun(locQuery);

    ttsbegin;

    this.insertTmpTableDataHeader();

    while (locQueryRun.next())
    {
        clssmmActivities = locQueryRun.get(tableNum(smmActivities));
        // insert data

        if(clssmmActivities.RecId)
        {
            this.insertTmpTableDataDetails();
        }
    }
    ttscommit;
}

/// <summary>
///     Gets the full data from the <c>AVASalesQuotRequestStatsReportHeaderTmp</c> temporary table.
/// </summary>
/// <returns>
///     The <c>AVAActivitiesWeeklyPlanReportHeaderTmp</c> temporary table.
/// </returns>
[SRSReportDataSetAttribute(tableStr(AVAActivitiesWeeklyPlanReportHeaderTmp))]
public AVAActivitiesWeeklyPlanReportHeaderTmp getHeaderTmp()
{
    AVAActivitiesWeeklyPlanReportHeaderTmp locTmpTable;

    this.setTransactionConnection(locTmpTable);

    select locTmpTable;

    return locTmpTable;
}

/// <summary>
///     Gets the full data from the <c>AVASalesQuotRequestStatsReportDetailTmp</c> temporary table.
/// </summary>
/// <returns>
///     The <c>AVAActivitiesWeeklyPlanReportDetailTmp</c> temporary table.
/// </returns>
[SRSReportDataSetAttribute(tableStr(AVAActivitiesWeeklyPlanReportDetailTmp))]
public AVAActivitiesWeeklyPlanReportDetailTmp getDetailTmp()
{
    AVAActivitiesWeeklyPlanReportDetailTmp locTmpTable;

    this.setTransactionConnection(locTmpTable);

    select  locTmpTable;

    return locTmpTable;
}

/// <summary>
///     Set the database transaction connection for a record from the connection associated with the report.
/// </summary>
/// <param name = "_reportRecord">
///     A record to set database transaction for.
/// </param>
final protected void setTransactionConnection(Common _reportRecord)
{
    var connection = this.parmUserConnection();

    if (connection)
    {
        _reportRecord.setConnection(connection);
    }
}

/// <summary>
///     AVA <c>processReport</c> method.
/// </summary>
public void setContractAndParamValues()
{
    Query                       locQuery;
    QueryBuildDataSource        locQueryBuildDataSource;
    QueryBuildRange             locQueryBuildRange;
    str                         locDateTimeRange;
    SalesQuotationTable         locSalesQuotationTable;
    smmBusRelTable              locsmmBusRelTable;
    CustTable                   locCustTable;
    CommissionSalesGroup        locCommissionSalesGroup;
    KCS_KBVRequestTable         locKCS_KBVRequestTable;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    clsCompanyInfo                  = CompanyInfo::find();
    clsCompanyLogo                  = CompanyImage::findByRecord(clsCompanyInfo);
    clsCompanyLogoBitmap            = clsCompanyLogo.Image;
    clsAllBPCompanies               = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    clsSysDocuBrandDetails          = SysDocuBrandDetails::getBrandDocument(this.parmDocuBrandContract());

    clsLanguageId                   = clsCompanyInfo.LanguageId;

    clsReportContract               = this.parmDataContract() as AVAsmmActivitiesWeeklyPlanADMReportContract;

    clsAVAEvaluationDateFrom        = clsReportContract.parmEvaluationDateFrom();
    clsAVAEvaluationDateTo          = clsReportContract.parmEvaluationDateTo();
    if(clsAVAEvaluationDateTo == dateNull())
    {
        clsAVAEvaluationDateToCalc = dateMax();
    }

    clsTimeZone                     = DateTimeUtil::getUserPreferredTimeZone();
    /*
    clsToday                        = DateTimeUtil::getToday(clsTimeZone);
    clsTodayDayOfWeek               = dayofwk(clsToday);
    if(clsTodayDayOfWeek == 1)
    {
        clsAVAEvaluationDateFromCalc    = clsToday;
    }
    else
    {
        clsAVAEvaluationDateFromCalc    = clsToday - (clsTodayDayOfWeek - 1);
    }
    clsAVAEvaluationDateToCalc          = clsAVAEvaluationDateFromCalc + (7 - 1);
    */
    //DatetimeUtil::Date(clsAVAEvaluationDateFromQuery)

    clsAVAEvaluationDateFromQuery   = DateTimeUtil::removeTimeZoneOffset(DateTimeUtil::newDateTime(clsAVAEvaluationDateFrom, 0), clsTimezone);
    clsAVAEvaluationDateToQuery     = DateTimeUtil::removeTimeZoneOffset(DateTimeUtil::newDateTime(clsAVAEvaluationDateTo, 86399), clsTimezone);

    locQuery = this.parmQuery();

    //smmActivities
    locQueryBuildDataSource = locQuery.dataSourceTable(tableNum(smmActivities));
    locQueryBuildRange      = SysQuery::findOrCreateRange(locQueryBuildDataSource, fieldNum(smmActivities, EndDateTime));
    locQueryBuildRange.value(SysQuery::range(clsAVAEvaluationDateFromQuery, clsAVAEvaluationDateToQuery));
}

/// <summary>
///     AVA <c>insertTmpTableData</c> method.
/// </summary>
public void insertTmpTableData()
{
    ttsbegin;
    if(0 == 0)
    {
        // Header infos
        this.insertTmpTableDataHeader();

        // Detail infos
        this.insertTmpTableDataDetails();
    }
    ttscommit;
}

/// <summary>
///    AVA <c>initHeaderTmp</c> method.
/// </summary>
/// <param name="_avaReportLineType">
///    <c>AVAReportLineType</c> as type
/// </param>
/// <param name="_additionalInfoNo">
///    <c>int</c> as type
/// </param>
public void initHeaderTmp(  AVAReportLineType   _avaReportLineType  = AVAReportLineType::HeaderLine, 
                            int                 _additionalInfoNo   = 0                             )
{
    clsAdditionalInfoLevel                  = _additionalInfoNo;

    this.setTransactionConnection(clsHeaderTmp);

    clsHeaderTmp.clear();
    clsHeaderTmp.AVAReportLineType          = _avaReportLineType;
    clsHeaderTmp.AdditionalInfoNo           = clsAdditionalInfoLevel;

    clsHeaderTmp.HeaderRecId                = 0;
}

/// <summary>
///    AVA <c>initDetailTmp</c> method.
/// </summary>
/// <param name="_avaReportLineType">
///    <c>AVAReportLineType</c> as type
/// </param>
/// <param name="_additionalInfoNo">
///    <c>int</c> as type
/// </param>
public void initDetailTmp(  AVAReportLineType   _avaReportLineType  = AVAReportLineType::DetailLine, 
                            int                 _additionalInfoNo   = 200                           )
{
    clsAdditionalInfoLevel          = _additionalInfoNo;

    this.setTransactionConnection(clsDetailTmp);

    clsDetailTmp.clear();
    clsDetailTmp.AVAReportLineType  = _avaReportLineType;
    clsDetailTmp.AdditionalInfoNo   = _additionalInfoNo;

    clsDetailTmp.Closed             = clssmmActivities.Closed;
    clsDetailTmp.ActivityNumber     = clssmmActivities.ActivityNumber;
    clsDetailTmp.Purpose            = clssmmActivities.Purpose;
    clsDetailTmp.TypeId             = clssmmActivities.TypeId;
    clsDetailTmp.Category           = clssmmActivities.Category;
    clsDetailTmp.StartDateTime      = clssmmActivities.StartDateTime;
    clsDetailTmp.EndDateTime        = clssmmActivities.EndDateTime;
    clsDetailTmp.ResponsibleWorker  = clssmmActivities.ResponsibleWorker;
    clsDetailTmp.DoneByWorker       = clssmmActivities.DoneByWorker;
}

/// <summary>
///    AVA <c>insertTmpTableDataHeader</c> method.
/// </summary>
public void insertTmpTableDataHeader()
{
    this.initHeaderTmp(AVAReportLineType::HeaderLine, 0);

    clsHeaderTmp.CompanyLogo                        = clsCompanyLogoBitmap;
    //clsHeaderTmp.CompanyGroupLogo                   = clsSysDocuBrandDetails.Image1;
    clsHeaderTmp.CompanyGroupLogo                   = conNull();    // no company group logo
    clsHeaderTmp.CompanyNotesLine1                  = clsSysDocuBrandDetails.NotesLine1;
    clsHeaderTmp.CompanyPromotionImage              = clsSysDocuBrandDetails.Image2;
    clsHeaderTmp.CompanyNotesLine2                  = clsSysDocuBrandDetails.NotesLine2;
    clsHeaderTmp.CompanyFooterImage                 = clsSysDocuBrandDetails.Image3;
    clsHeaderTmp.CompanyNotesLine3                  = clsSysDocuBrandDetails.NotesLine3;
    clsHeaderTmp.CompanyAddressLine                 = clsSysDocuBrandDetails.AVASender;
    clsHeaderTmp.CompanyPostalAddressing            = clsCompanyInfo.postalAddress().Address;
    clsHeaderTmp.CompanyPostalAddressingSingleLine  = AVAHelperClass::adress2singleLineFormat('', clsHeaderTmp.CompanyPostalAddressing);

    // parameter values
    clsHeaderTmp.EvaluationDateFrom                 = clsReportContract.parmEvaluationDateFrom();
    clsHeaderTmp.EvaluationDateTo                   = clsReportContract.parmEvaluationDateTo();

    clsHeaderTmp.insert();
}

/// <summary>
///    AVA <c>insertTmpTableDataDetails</c> method.
/// </summary>
public void insertTmpTableDataDetails()
{
    HCMWorker   locHCMWorker;
    date        locReleaseDate;

    this.initDetailTmp(AVAReportLineType::DetailLine, 400);

    clsDetailTmp.StartDateDayOfWeek = this.getDayOfWeekToDate(any2date(DateTimeUtil::applyTimeZoneOffset(clsDetailTmp.StartDateTime, clsTimeZone)));
    clsDetailTmp.EndDateDayOfWeek   = this.getDayOfWeekToDate(any2date(DateTimeUtil::applyTimeZoneOffset(clsDetailTmp.EndDateTime, clsTimeZone)));

    if(clssmmActivities.ResponsibleWorker)
    {
        locHCMWorker                        = null;
        locHCMWorker                        = HcmWorker::find(clssmmActivities.ResponsibleWorker);
        clsDetailTmp.ResponsibleWorkerName  = locHCMWorker.name();
    }
    if(clssmmActivities.DoneByWorker)
    {
        locHCMWorker                        = null;
        locHCMWorker                        = HcmWorker::find(clssmmActivities.DoneByWorker);
        clsDetailTmp.DoneByWorkerName       = locHCMWorker.name();
    }
    clsDetailTmp.LinkedParentName           = clssmmActivities.avaDisplayLinkedParentName();

    locReleaseDate                  = dateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(clssmmActivities.StartDateTime, clsTimezone));
    clsDetailTmp.CalendarWeek       = wkOfYr(any2date(locReleaseDate));
    clsDetailTmp.MonthInt           = mthOfYr(locReleaseDate);
    clsDetailTmp.YearInt            = year(locReleaseDate);

    clsDetailTmp.HeaderTxt          = '';
    clsDetailTmp.HeaderTxt          += SysLabel::labelId2String2(literalStr("@NDX:NXAADMWeeklyPlan"), clsLanguageId);
    clsDetailTmp.HeaderTxt          += ' ';
    clsDetailTmp.HeaderTxt          += clsDetailTmp.ResponsibleWorkerName;
    clsDetailTmp.HeaderTxt          += ' ';
    clsDetailTmp.HeaderTxt          += SysLabel::labelId2String2(literalStr("@GLS109961"), clsLanguageId);
    clsDetailTmp.HeaderTxt          += ' ';
    clsDetailTmp.HeaderTxt          += strFmt("%1", clsDetailTmp.CalendarWeek);

    clsDetailTmp.insert();

    clsAdditionalInfoLevel++;
}

/// <summary>
///     AVA <c>getDayOfWeekToDate</c> method.
/// </summary>
/// <param name="_date2check">
///     <c>date</c> as type
/// </param>
/// <returns>
///     <c>smmDaysOfWeek</c> as return value
/// </returns>
public smmDaysOfWeek getDayOfWeekToDate(date _date2check)
{
    smmDaysOfWeek retVal;

    int locDayOfWeek = dayOfWk(_date2check);

    switch(locDayOfWeek)
    {
        case 1:
            retVal = smmDaysOfWeek::Monday;
            break;

        case 2:
            retVal = smmDaysOfWeek::Tuesday;
            break;

        case 3:
            retVal = smmDaysOfWeek::Wednesday;
            break;

        case 4:
            retVal = smmDaysOfWeek::Thursday;
            break;

        case 5:
            retVal = smmDaysOfWeek::Friday;
            break;

        case 6:
            retVal = smmDaysOfWeek::Saturday;
            break;

        case 7:
            retVal = smmDaysOfWeek::Sunday;
            break;
    }
    return retVal;
}
